DO $$ DECLARE pedido jsonb; resultado jsonb; BEGIN
 pedido:=(public.membros_ferramentas_admin()->'exclusoes')->0;
 resultado:=public.membros_crm_excluir_pedido((pedido->>'user_id')::uuid,(pedido->>'produto_id')::uuid,(pedido->>'solicitado_em')::timestamptz);
 PERFORM public.testar((resultado->>'contatos')::int=1 AND (resultado->>'negocios')::int=1,'pedido exclui somente os registros do CRM solicitado');
 PERFORM public.testar(jsonb_array_length(public.membros_ferramentas_admin()->'exclusoes')=0,'pedido atendido deixa de aparecer como pendente');
 BEGIN PERFORM public.membros_crm_excluir_pedido((pedido->>'user_id')::uuid,(pedido->>'produto_id')::uuid,(pedido->>'solicitado_em')::timestamptz); RAISE EXCEPTION 'Pedido foi atendido duas vezes';
 EXCEPTION WHEN invalid_parameter_value THEN PERFORM public.testar(true,'exclusão não repete uma decisão já atendida'); END;
END $$;
