DO $$ DECLARE v uuid; BEGIN
 v:=public.membros_conteudo_versionar('40000000-0000-0000-0000-000000000001','rascunhar','{"titulo":"Nova versão revisada","texto":"Conteúdo aprovado de teste","estado":"publicado"}');
 PERFORM public.testar(NOT EXISTS(SELECT 1 FROM jsonb_array_elements(public.membros_acervo('30000000-0000-0000-0000-000000000001')->'materiais') m WHERE m->>'titulo'='Nova versão revisada'),'rascunho não altera o que o membro já vê');
 BEGIN PERFORM public.membros_conteudo_versionar('40000000-0000-0000-0000-000000000001','publicar',NULL,v); RAISE EXCEPTION 'Publicou sem revisão';
 EXCEPTION WHEN invalid_parameter_value THEN PERFORM public.testar(true,'sem aprovação não publica'); END;
 PERFORM public.membros_conteudo_versionar('40000000-0000-0000-0000-000000000001','enviar_revisao',NULL,v);
 PERFORM public.membros_conteudo_versionar('40000000-0000-0000-0000-000000000001','aprovar',NULL,v);
 PERFORM public.membros_conteudo_versionar('40000000-0000-0000-0000-000000000001','publicar',NULL,v);
 PERFORM public.testar(EXISTS(SELECT 1 FROM jsonb_array_elements(public.membros_acervo('30000000-0000-0000-0000-000000000001')->'materiais') m WHERE m->>'titulo'='Nova versão revisada' AND m->>'texto'='Conteúdo aprovado de teste'),'publicação usa exatamente o conteúdo aprovado');
 PERFORM public.testar(jsonb_array_length(public.membros_conteudo_versoes_ler('40000000-0000-0000-0000-000000000001'))=1,'versão publicada continua no histórico');
END $$;
