SELECT public.testar(NOT EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN('membros_ferramentas','membros_licencas','membros_sessoes_ferramenta','membros_crm_contatos','membros_crm_negocios','membros_ferramentas_historico','membros_pedidos_exclusao','membros_conteudo_versoes','membros_canais') AND NOT c.relrowsecurity),'todas as tabelas do lote têm RLS');
SELECT public.testar(NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE p.prosecdef AND (n.nspname='membros_privado' OR (n.nspname='public' AND p.proname LIKE 'membros_%')) AND NOT COALESCE('search_path=""'=ANY(p.proconfig),false)),'funções privilegiadas usam busca fixa');
